import math

def count_divisors(n):
    """Calculates tau(n), the number of divisors of n."""
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def is_exotic_tau(tau_n):
    """Checks if tau(n) is twice an odd integer."""
    if tau_n % 2 != 0:
        return False # Must be even
    half_tau = tau_n // 2
    return half_tau % 2 != 0

def find_kth_exotic_n(k):
    """Finds the k-th smallest positive integer n such that tau(n) is twice an odd integer."""
    count = 0
    n = 1
    while count < k:
        tau_n = count_divisors(n)
        if is_exotic_tau(tau_n):
            count += 1
            if count == k:
                return n
        n += 1
    return None

